<?php require '../config.php';require_admin();$adminPage=true;$pageTitle='Quản lý danh mục';$error='';if(isset($_GET['delete'])){try{$st=$pdo->prepare('DELETE FROM categories WHERE category_id=?');$st->execute([(int)$_GET['delete']]);header('Location: categories.php?deleted=1');exit;}catch(PDOException $e){$error='Không thể xóa danh mục đang được sản phẩm sử dụng.';}}$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM categories WHERE category_id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['category_id']??0);$name=trim($_POST['category_name']??'');$desc=trim($_POST['description']??'');if($name==='')$error='Tên danh mục không được để trống.';else{try{if($id){$st=$pdo->prepare('UPDATE categories SET category_name=?,description=? WHERE category_id=?');$st->execute([$name,$desc,$id]);}else{$st=$pdo->prepare('INSERT INTO categories(category_name,description) VALUES(?,?)');$st->execute([$name,$desc]);}header('Location: categories.php?saved=1');exit;}catch(PDOException $e){$error='Tên danh mục có thể đã tồn tại.';}}}$cats=$pdo->query('SELECT c.*,COUNT(p.product_id) product_count FROM categories c LEFT JOIN products p ON c.category_id=p.category_id GROUP BY c.category_id ORDER BY c.category_id DESC')->fetchAll();require '../includes/header.php';?><div class="row g-4"><div class="col-md-3"><?php require 'nav.php';?></div><div class="col-md-9"><h1 class="section-title">Quản lý danh mục</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="content-card mb-4"><h5><?= $edit?'Sửa danh mục':'Thêm danh mục' ?></h5><input type="hidden" name="category_id" value="<?= (int)($edit['category_id']??0) ?>"><div class="mb-3"><label class="form-label">Tên danh mục</label><input class="form-control" name="category_name" required value="<?= e($edit['category_name']??'') ?>"></div><div class="mb-3"><label class="form-label">Mô tả</label><textarea class="form-control" name="description"><?= e($edit['description']??'') ?></textarea></div><button class="btn btn-red">Lưu danh mục</button> <?php if($edit): ?><a class="btn btn-outline-secondary" href="categories.php">Hủy</a><?php endif; ?></form><div class="content-card table-responsive"><table class="table"><thead><tr><th>ID</th><th>Tên</th><th>Mô tả</th><th>Số sản phẩm</th><th></th></tr></thead><tbody><?php foreach($cats as $c): ?><tr><td><?= $c['category_id'] ?></td><td><?= e($c['category_name']) ?></td><td><?= e($c['description']) ?></td><td><?= $c['product_count'] ?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="?edit=<?= $c['category_id'] ?>">Sửa</a> <a class="btn btn-sm btn-outline-danger" href="?delete=<?= $c['category_id'] ?>" onclick="return confirm('Xóa danh mục này?')">Xóa</a></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php require '../includes/footer.php';?>
